/** A stock-keeping item (auto part) as returned by the API. */
export interface Item {
  id: string;
  /** Human-facing code, generated by the server (e.g. `IT-00042`). */
  code: string;
  name: string;
  groupId: string;
  groupName: string;
  groupColor: string;
  unit: ItemUnit;
  /** Letters and/or digits, unique when set (409 `BARCODE_TAKEN`). */
  barcode: string;
  /** Optional digits-only stock-keeping number, unique (409 `SKU_TAKEN`). Not the auto `code`. */
  sku: string | null;
  brand: string;
  purchasePrice: number;
  salePrice: number;
  /** 0–100. Shown to customers in the mobile app as a sale price cut. */
  discountPercent: number;
  /** Reorder level — below it the item is flagged as low stock. */
  minStock: number;
  stock: number;
  description: string;
  /** Free-text compatibility ("تويوتا كورولا 2014–2019، ياريس 2016"), ≤ 500 chars. Searchable. Separate from fitments. */
  compatibleWith: string | null;
  isActive: boolean;
  createdAt: string;

  // ── Computed by the server (read-only) ──
  /** Average of VISIBLE reviews, 1 decimal; 0 = no reviews. */
  averageRating: number;
  /** Number of visible reviews. */
  reviewsCount: number;
}

export type ItemPayload = Pick<
  Item,
  | 'name'
  | 'groupId'
  | 'unit'
  | 'barcode'
  | 'sku'
  | 'brand'
  | 'purchasePrice'
  | 'salePrice'
  | 'discountPercent'
  | 'minStock'
  | 'description'
  | 'compatibleWith'
  | 'isActive'
>;

/** Max length of `compatibleWith` (server returns 422 beyond it). */
export const COMPATIBLE_WITH_MAX = 500;

/** Business-rule codes the items API answers with (409). */
export const ITEM_ERROR_CODES = {
  /** Item has stock movements — can never be deleted, only deactivated. */
  hasMovements: 'ITEM_HAS_MOVEMENTS',
  /** Group still contains items. */
  groupHasItems: 'GROUP_HAS_ITEMS',
  /** The chosen group has sub-groups — items attach to leaf groups only. */
  groupNotLeaf: 'GROUP_NOT_LEAF',
  skuTaken: 'SKU_TAKEN',
  barcodeTaken: 'BARCODE_TAKEN',
} as const;

/** Uniqueness conflicts (409) → the form control they belong to. */
export const ITEM_CONFLICT_FIELD: Readonly<Record<string, 'sku' | 'barcode' | 'groupId'>> = {
  [ITEM_ERROR_CODES.skuTaken]: 'sku',
  [ITEM_ERROR_CODES.barcodeTaken]: 'barcode',
  [ITEM_ERROR_CODES.groupNotLeaf]: 'groupId',
};

export const DISCOUNT_RANGE = { min: 0, max: 100 } as const;

/** Sale price after the item discount, rounded to piasters. */
export function discountedPrice(salePrice: number, discountPercent: number): number {
  const pct = Math.min(DISCOUNT_RANGE.max, Math.max(DISCOUNT_RANGE.min, discountPercent || 0));
  return Math.round(salePrice * (1 - pct / 100) * 100) / 100;
}

/** Full update payload from a loaded item (e.g. to toggle `isActive`). */
export function toItemPayload(item: Item, patch: Partial<ItemPayload> = {}): ItemPayload {
  const { name, groupId, unit, barcode, sku, brand, purchasePrice, salePrice, discountPercent, minStock, description, compatibleWith, isActive } =
    item;
  return {
    name,
    groupId,
    unit,
    barcode,
    sku: sku ?? null,
    brand,
    purchasePrice,
    salePrice,
    discountPercent: discountPercent ?? 0,
    minStock,
    description,
    compatibleWith,
    isActive,
    ...patch,
  };
}

export const ITEM_UNITS =['قطعة', 'طقم', 'لتر', 'علبة', 'كرتونة', 'متر', 'زوج'] as const;
export type ItemUnit = (typeof ITEM_UNITS)[number];

export type StockLevel = 'out' | 'low' | 'ok';

export function stockLevel(item: Pick<Item, 'stock' | 'minStock'>): StockLevel {
  if (item.stock <= 0) return 'out';
  return item.stock <= item.minStock ? 'low' : 'ok';
}

export const STOCK_LEVEL_LABEL: Record<StockLevel, string> = {
  out: 'نفد',
  low: 'منخفض',
  ok: 'متوفر',
};

/** Gross margin as a percentage of the sale price (0 when there is no price). */
export function marginPct(purchase: number, sale: number): number {
  return sale > 0 ? Math.round(((sale - purchase) / sale) * 1000) / 10 : 0;
}
